def compute(vars):
    old = vars["v2"]
    new = vars["v1"]
    value = new - old

    return {
        "value": value,
        "trace": {
            "old": old,
            "new": new,
            "difference": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "Number"
            }
        }
    }
